contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call getFirstWithdrawalBonus on some recipient address and observe:
    // - whether the call reverted; if it did not revert, then the recipient must have been marked as claimed
    //   (via the public getter claimedBonus) and the contract's balance must have decreased by exactly 100
    //   (since getFirstWithdrawalBonus adds 100 to rewardsForA and then withdraws it).
    // Note: recipient is any address; we use msg.sender of c calls implicitly (InvMutTest) but recipient can be arbitrary.
    function run(address payable recipient) public payable {
        require(true);

        // record c balance before
        uint balanceBefore = address(c).balance;

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observed claimed flag after attempt
        bool claimedAfter = c._locked() /* just to call a public getter to ensure no compile error */ ? c._locked() : c._locked();
        // NOTE: claimedBonus is private so no getter; instead we observe claimed by checking that
        // if the call succeeded then the contract balance decreased by 100 (the withdrawn bonus),
        // and if it succeeded then a subsequent call to getFirstWithdrawalBonus for same recipient must revert
        // (because claimedBonus[recipient] would be true). We'll implement the final assert accordingly.

        // To check the post-condition when call succeeded, attempt the second call and see if it reverts.
        bool revertedSecond;
        try c.getFirstWithdrawalBonus(recipient) {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }

        uint balanceAfter = address(c).balance;

        // General rule asserted:
        // If the first call reverted, nothing required here (we allow revert). If it did not revert then:
        //  - the contract's balance decreased by exactly 100 (balanceBefore == balanceAfter + 100)
        //  - a second call for same recipient must revert (claimedBonus was set)
        assert(reverted || (balanceBefore == balanceAfter + 100 && revertedSecond));
    }

    // No special receive logic needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We assert: if recipient is not this contract, then either the call reverts or
    // the contract's balance decreases by exactly 100.
    function run(address payable recipient) public payable {
        require(recipient != payable(address(this)));

        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balanceAfter = address(c).balance;

        assert(reverted || balanceBefore == balanceAfter + 100);
    }

    receive() external payable {}
}

