contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call getFirstWithdrawalBonus on some recipient address.
    // Because the test contract is the deployer and caller of c in this environment,
    // we use an arbitrary recipient parameter and observe public getters.

    function run(address recipient) public payable {
        require(true);

        // Record contract balance before the call
        uint beforeBalance = address(c).balance;

        // Try the call and record whether it reverted
        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe public state we can read: _locked (public in parent SmartFix)
        // and address(c).balance. Also C has no public getters for claimedBonus or rewardsForA,
        // but claimedBonus and rewardsForA are private, so we cannot read them directly.
        // However, withdrawReward sends Ether to recipient; if the call succeeded then the contract
        // must have transferred 100 wei to recipient from rewardsForA. We can observe contract balance.

        uint afterBalance = address(c).balance;

        // General rule (expressed with available observations):
        // If the call reverted, contract balance must be unchanged. If it did not revert, contract
        // balance must have decreased by exactly 100 (the bonus added then withdrawn), and the contract
        // must not be left in locked state (_locked == false).

        assert(
            (reverted && afterBalance == beforeBalance) ||
            (!reverted && beforeBalance >= afterBalance && beforeBalance - afterBalance == 100 && c._locked() == false)
        );
    }

    receive() external payable { }
}
